    for ink in ink_colors:
        for top in range(h):
            for bottom in range(top + 2, h):
                for left in range(w):
                    for right in range(left + 2, w):
                        # A line can have a one-cell gap when another stroke
                        # continues through that point; otherwise require it complete.
                        side_cells = [
                            [grid[top][c] for c in range(left, right + 1)],
                            [grid[bottom][c] for c in range(left, right + 1)],
                            [grid[r][left] for r in range(top, bottom + 1)],
                            [grid[r][right] for r in range(top, bottom + 1)],
                        ]
                        edge_missing = [top == 0, bottom == h - 1, left == 0, right == w - 1]
                        solid = [sum(v == ink for v in side) for side in side_cells]
                        lengths = [len(side) for side in side_cells]
                        # Require three clear sides, or two plus an edge-open side;
                        # permit one interrupted pixel in the remaining contour.
                        valid = [edge_missing[i] or solid[i] == lengths[i] for i in range(4)]
                        if sum(valid) < 3:
