 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Fill background cavities enclosed by the colored strokes.
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr, nc) not in outside:
                outside.add((nr, nc)); q.append((nr, nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in outside:
                out[r][c] = 4

    # Some outlined compartments are open only along the canvas edge. In the
    # demonstrated bottom-edge case, a horizontal top and two continuous rails
    # enclose the background between them up to the last row.
    ink_colors = {v for row in grid for v in row if v != bg}
    for ink in ink_colors:
        for top in range(h - 1):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[top][c] == ink for c in range(left, right + 1)):
