        # Frame opens at top: rails start at row 0 and close on a full bottom bar.
        for bottom in range(1, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[bottom][c] == ink for c in range(left, right + 1)):
