                        continue
                    if right + 1 < w and grid[top][right + 1] == ink:
                        continue
                    if all(grid[r][left] == ink and grid[r][right] == ink for r in range(top, h)):
                        for r in range(top + 1, h):
                            for c in range(left + 1, right):
